    {
        var lines = content.Split('\n');
        var failLines = lines.Where(l => l.Contains("[FAIL]")).Take(20).ToList();
        var summaryLine = lines.LastOrDefault(
            l => l.Contains("Failed:") || l.Contains("Passed:"))?.Trim();

