    private static string MergeChecksEvidence(string checksPath, string existingSummary)
    {
        using var doc = JsonDocument.Parse(File.ReadAllText(checksPath));
        var root = doc.RootElement;

        var sb = new StringBuilder();

        AppendCheckSection(sb, "guard", root);
        AppendCheckSection(sb, "bootstrap", root);
        AppendCheckSection(sb, "newGuardProbe", root);

        if (sb.Length > 0 && !string.IsNullOrEmpty(existingSummary))
            sb.AppendLine();
        sb.Append(existingSummary);

        return sb.ToString().TrimEnd();
    }

    private static void AppendCheckSection(StringBuilder sb, string checkName, JsonElement root)
    {
        var checkProp = $"{checkName}Check";
        if (!root.TryGetProperty(checkProp, out var checkEl)
            || checkEl.ValueKind != JsonValueKind.String)
        {
            return;
        }

        var value = checkEl.GetString();
        if (!string.Equals(value, "red", StringComparison.OrdinalIgnoreCase))
            return;

        // Look for the corresponding output.
        string? output = null;
        var outputProp = $"{checkName}Output";
        if (root.TryGetProperty(outputProp, out var outEl)
            && outEl.ValueKind == JsonValueKind.String)
        {
            output = outEl.GetString();
        }

        sb.AppendLine($"{checkName} check: red");

        if (!string.IsNullOrWhiteSpace(output))
        {
            var capped = CapOutput(output, maxLines: 40, maxChars: 4_000);
            sb.Append(capped);
        }
    }

    private static string ReadTailCapped(string filePath, int maxLines, int maxChars)
    {
        try
        {
            var lines = File.ReadAllLines(filePath);
            if (lines.Length > maxLines)
                lines = lines[^maxLines..];

            var joined = string.Join('\n', lines);
            if (joined.Length > maxChars)
                joined = joined[^maxChars..];

            return joined;
        }
        catch
        {
            return string.Empty;
        }
    }

    private static string CapOutput(string text, int maxLines, int maxChars)
    {
        var lines = text.Split('\n');
        if (lines.Length > maxLines)
            lines = lines[^maxLines..];

        var joined = string.Join('\n', lines);
        if (joined.Length > maxChars)
            joined = joined[^maxChars..];

        return joined;
    }
}

